"""Static interactive dashboard; data and assets replaced each successful run."""
import html
import json
from pathlib import Path

CSS='''
:root{color-scheme:dark;--bg:#080f1c;--card:#111d30;--line:#243449;--muted:#a4b7c9;--ink:#ecf3fb;--accent:#7cc6ff;--positive:#7ee4b2}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.55 ui-sans-serif,system-ui,Segoe UI,Arial,sans-serif}a{color:var(--accent)}header{padding:22px max(20px,calc((100vw - 1240px)/2));border-bottom:1px solid var(--line);background:#0c1627}h1{font-size:clamp(1.55rem,3vw,2.5rem);margin:0}h2{font-size:1.3rem;margin:0 0 14px}h3{font-size:1.05rem;margin:0}p{margin:7px 0}main{max-width:1240px;margin:auto;padding:24px 20px 60px}.subtitle,.meta,.muted{color:var(--muted)}.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px;margin:20px 0}.stat,.panel,.story{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:17px}.stat strong{display:block;font-size:2rem;line-height:1.3}.stat span{color:var(--muted);font-size:.84rem}.panel{margin:18px 0}.panel p{color:#d6e3ef}.nav{display:flex;gap:8px;overflow-x:auto;padding:4px 0 12px;scrollbar-width:thin}.tab{background:#142339;border:1px solid var(--line);padding:10px 14px;border-radius:10px;color:var(--ink);cursor:pointer;white-space:nowrap}.tab.active{background:#173e60;border-color:var(--accent)}.tab:focus-visible,button:focus-visible{outline:2px solid var(--accent);outline-offset:2px}.tab span{color:var(--muted);margin-left:6px}.section-head{display:flex;justify-content:space-between;gap:12px;align-items:center;flex-wrap:wrap}.tools{display:flex;gap:10px;flex-wrap:wrap;margin:15px 0}input,select{background:#0b1626;border:1px solid #34485d;color:white;border-radius:10px;padding:10px 12px;min-width:190px}button{font:inherit}.stories{display:grid;gap:12px;margin:16px 0}.story{padding:16px}.story h3 a{text-decoration:none}.story h3 a:hover{text-decoration:underline}.story .meta{font-size:.82rem;margin:6px 0}.tag{display:inline-block;border:1px solid #47637d;border-radius:12px;padding:2px 8px;margin-right:6px;font-size:.76rem;color:#cae5fa}.hi{color:#89e7b7;border-color:#30755a}.summary{color:#ccdae9}.small{font-size:.83rem}.expand{background:none;border:1px solid #3d617d;color:var(--accent);padding:9px 15px;border-radius:10px;cursor:pointer}.hidden{display:none!important}.blank{color:var(--muted);padding:18px}footer{color:var(--muted);border-top:1px solid var(--line);padding:22px;text-align:center}.two{display:grid;grid-template-columns:1fr 1fr;gap:14px}.category-metrics{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:12px}.category-metrics span{background:#172b41;border-radius:10px;padding:7px 12px}.source-form{display:flex;gap:10px;flex-wrap:wrap;align-items:center}.source-form input{flex:1;min-width:240px}.source-form select{min-width:150px}.source-form button{background:#1972ae;color:white;border:0;border-radius:10px;padding:10px 18px;cursor:pointer}.source-form button:hover{background:#2388cb}.source-help{color:var(--muted);font-size:.86rem}.health-table{width:100%;border-collapse:collapse;font-size:.82rem}td,th{text-align:left;border-bottom:1px solid var(--line);padding:9px;overflow-wrap:anywhere}.tablewrap{overflow:auto}@media(max-width:700px){.two{grid-template-columns:1fr}.stats{grid-template-columns:repeat(2,minmax(0,1fr))}.stat strong{font-size:1.5rem}}
'''
JS=r'''
const el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n};
const fmt=iso=>{let d=new Date(iso);return isNaN(d)?'Unknown date':d.toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short',timeZone:'UTC'})+' UTC'};
let report=null,active='Top stories',showAll=false;
const byId=id=>document.getElementById(id);
function storyCard(s){const box=el('article','story');const h=el('h3');const a=el('a',null,s.title);a.href=s.url;a.target='_blank';a.rel='noopener noreferrer';h.append(a);box.append(h);const m=el('p','meta',s.source+' · '+fmt(s.published));box.append(m);const tags=el('div');tags.append(el('span','tag '+(s.priority==='High signal'?'hi':''),s.priority));tags.append(el('span','tag','Signal '+s.score));if(s.coverage?.length)tags.append(el('span','tag',(s.coverage.length+1)+' coverage links'));box.append(tags);box.append(el('p','summary',s.summary? s.summary.slice(0,450):'Open the primary source for details.'));if(s.coverage?.length){let cov=el('p','small');cov.append('Also covered: ');s.coverage.slice(0,4).forEach((c,i)=>{if(i)cov.append(' · ');let a=el('a',null,c.source);a.href=c.url;a.rel='noopener noreferrer';a.target='_blank';cov.append(a)});box.append(cov)}return box}
function addSource(){
 const field=byId('new-source-url'),category=byId('new-source-category').value;
 const raw=field.value.trim();let u;
 try{u=new URL(raw)}catch(_){byId('source-feedback').textContent='Enter a complete https:// URL.';return}
 if(u.protocol!=='https:'||!u.hostname||u.username||u.password){byId('source-feedback').textContent='Only public HTTPS links without credentials are accepted.';return}
 const body='URL: '+u.toString()+'\nCategory: '+category+'\nName: '+u.hostname+'\n';
 const repo='franciselhelou/daily-digest';
 const link='https://github.com/'+repo+'/issues/new?title='+encodeURIComponent('[Add Source] '+u.hostname)+'&body='+encodeURIComponent(body);
 byId('source-feedback').textContent='On GitHub, click Submit new issue to confirm. The source will then be validated and added automatically.';
 window.open(link,'_blank','noopener,noreferrer');
}
function render(){const cats=report.categories;byId('tabs').replaceChildren();for(const cat of [{name:'Top stories',count:report.top.length},...cats]){let button=el('button','tab'+(active===cat.name?' active':''),cat.name);button.setAttribute('aria-pressed',String(active===cat.name));button.append(el('span',null,cat.count));button.onclick=()=>{active=cat.name;showAll=false;render()};byId('tabs').append(button)}const selected=cats.find(c=>c.name===active),list=selected?selected.items:report.top;byId('category-name').textContent=active;byId('category-metrics').replaceChildren();if(selected){for(const value of [selected.count+' unique developments',selected.high+' high-signal findings'])byId('category-metrics').append(el('span',null,value))}else byId('category-metrics').append(el('span',null,'Top '+report.top.length+' ranked events'));
byId('category-summary').textContent=selected?selected.narrative:report.executive;
const q=byId('query').value.toLowerCase().trim(),priority=byId('priority').value;let matched=list.filter(s=>(!q||(s.title+' '+s.summary+' '+s.source).toLowerCase().includes(q))&&(priority==='all'||s.priority===priority));let visible=(showAll||q||priority!=='all')?matched:matched.slice(0,selected?3:10);byId('results').replaceChildren(...visible.map(storyCard));if(!visible.length)byId('results').append(el('p','blank','No matching stories.'));const button=byId('show-more');button.classList.toggle('hidden',matched.length<= (selected?3:10)||!!q||priority!=='all');button.textContent=showAll?'Show fewer':`Show remaining ${Math.max(0,matched.length-(selected?3:10))} stories`}
async function start(){byId('add-source').onclick=addSource;byId('new-source-url').addEventListener('keydown',e=>{if(e.key==='Enter')addSource()});try{let res=await fetch('./data.json',{cache:'no-store'});if(!res.ok)throw Error('HTTP '+res.status);report=await res.json();const s=report.stats;const stats=[['Unique 24h events',s.events],['High-signal candidates',s.high],['Reporting sources',s.sources_reporting],['Categories',s.categories],['Feed checks failed',s.sources_failed]];byId('stats').replaceChildren(...stats.map(([label,value])=>{let b=el('div','stat');b.append(el('strong',null,String(value)));b.append(el('span',null,label));return b}));byId('generated').textContent='Updated '+fmt(report.generated)+' · Strict rolling 24-hour window';byId('executive').textContent=report.executive;byId('show-more').onclick=()=>{showAll=!showAll;render()};byId('query').oninput=render;byId('priority').onchange=render;let failed=report.health.filter(h=>h.status!=='ok');byId('health-count').textContent=failed.length+' source issues / '+report.stats.source_checks+' checks';const tbody=byId('health-body');for(let h of failed){let tr=el('tr');for(let val of [h.source,h.kind,h.error?.slice(0,170)||'Unavailable',String(h.failures)])tr.append(el('td',null,val));tbody.append(tr)}if(!failed.length){let tr=el('tr');tr.append(el('td',null,'No recorded source errors'));tbody.append(tr)}render()}catch(error){byId('executive').textContent='Cannot load daily report: '+error.message+' — check that docs/data.json was generated and deployed.'}}
start();
'''
HTML='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'self'; style-src 'self'; connect-src 'self'; base-uri 'none'; form-action 'none'"><title>AI Intelligence | Daily Dashboard</title><link rel="stylesheet" href="./style.css"></head><body><header><h1>AI Intelligence Dashboard</h1><div id="generated" class="subtitle">Loading latest daily report…</div></header><main><div id="stats" class="stats"></div><section class="panel"><h2>Executive intelligence brief</h2><p id="executive">Loading…</p><p class="small muted">Priority scores are screening signals, not proof of a validated technological breakthrough. All findings link to their sources.</p></section><section class="panel"><h2>Explore categories</h2><nav class="nav" id="tabs" aria-label="Categories"></nav><div class="section-head"><h2 id="category-name">Top stories</h2><div id="category-metrics" class="category-metrics"></div></div><p id="category-summary"></p><div class="tools"><input id="query" aria-label="Search stories" placeholder="Search titles and summaries"><select id="priority" aria-label="Priority filter"><option value="all">All priorities</option><option value="High signal">High signal</option><option value="Worth watching">Worth watching</option><option value="Other developments">Other developments</option></select></div><div class="stories" id="results"></div><button type="button" class="expand hidden" id="show-more">Show more</button></section><section class="panel"><h2>Add a new intelligence source</h2><p class="source-help">Found a useful AI news site, newsletter, or research feed? Paste its HTTPS URL. GitHub will ask you to confirm the submission; an automated workflow will validate it and add it to the repository source list. RSS/Atom feed URLs work best. Ordinary webpages may be recorded but may not produce findings unless they expose a discoverable feed.</p><div class="source-form"><input type="url" id="new-source-url" placeholder="https://example.com/ai/feed" aria-label="New source URL"><select id="new-source-category" aria-label="Source category"><option>Research</option><option>Security</option><option>Agents</option><option>Robotics</option><option>Models</option><option>Governance</option><option>Enterprise</option><option>Engineering</option><option>Open source</option><option>Hardware</option><option>News</option><option>Regional</option><option>Quantum</option><option>Community</option></select><button type="button" id="add-source">Add source</button></div><p class="source-help" id="source-feedback" aria-live="polite"></p></section><details class="panel"><summary><strong>Source health</strong> — <span id="health-count"></span></summary><p class="muted small">401/403 mean access restrictions; 429 rate limiting; 404 usually an invalid or removed endpoint. These failures are not evidence that the publisher is inactive.</p><div class="tablewrap"><table class="health-table"><thead><tr><th>Source</th><th>Type</th><th>Latest error</th><th>Consecutive failures</th></tr></thead><tbody id="health-body"></tbody></table></div></details><p class="muted small"><a href="./latest.md">Plain Markdown digest</a> · <a href="./source-health.md">Full source health report</a></p></main><footer>Built from dated evidence collected within the preceding 24 hours. Updates replace the previous dashboard.</footer><script src="./app.js" defer></script></body></html>'''

def write_dashboard(docs:Path, report):
    docs.mkdir(parents=True,exist_ok=True)
    (docs/'index.html').write_text(HTML,encoding='utf-8')
    (docs/'app.js').write_text(JS,encoding='utf-8')
    (docs/'style.css').write_text(CSS,encoding='utf-8')
    (docs/'data.json').write_text(json.dumps(report,ensure_ascii=False,indent=2).replace('</','<\\/'),encoding='utf-8')

def markdown(report):
    s=report['stats'];lines=['# Daily AI Intelligence Digest','',f"**Generated:** {report['generated']}  ", '**Window: last 24 hours (UTC, rolling)**  ',f"**Distinct events:** {s['events']} · **High-signal candidates:** {s['high']} · **Sources reporting:** {s['sources_reporting']}",'','## Executive brief','',report['executive'],'','## Top stories','']
    def add(row):
        title=row['title'].replace('[','\\[').replace(']','\\]').replace('|','\\|')
        # URLs originate in feeds, avoid untrusted markdown control characters.
        url=row['url'].replace(')','%29').replace('(','%28')
        lines.extend([f"### [{title}]({url})",'',f"**{row['category']} · {row['priority']} · Score {row['score']} · {row['source']}**",'',row.get('summary','')[:300].replace('<','&lt;').replace('>','&gt;'),''])
    for row in report['top']:add(row)
    for cat in report['categories']:
        lines += [f"## {cat['name']} — {cat['count']} distinct findings, {cat['high']} high-signal",'',cat['narrative'],'']
        for row in cat['top']:add(row)
    lines+=['---','', 'See the interactive GitHub Pages dashboard for category filters and lower-priority findings. Ratings are heuristic, not independently verified impact assessments.']
    return '\n'.join(lines)+'\n'
